@Test
void testBinomialCoefficientLarge() throws Exception {
    // This tests all legal and illegal values for n <= 200.
    for (int n = 0; n <= 200; n++) {
        for (int k = 0; k <= n; k++) {
            long ourResult = -1;
            long exactResult = -1;
            boolean shouldThrow = false;
