@Test
void testParseAndToString() {
    final double[] parts = { Double.NEGATIVE_INFINITY, -1, -0.0, 0.0, 1, Math.PI, Double.POSITIVE_INFINITY, Double.NaN };
    for (final double x : parts) {
        for (final double y : parts) {
