@Test
void testParse() {
    final String[] validExpressions = new String[] { "1 / 2", "-1 / 2", "1 / -2", "-1 / -2", "01 / 2", "01 / 02", "-01 / 02", "01 / -02", "15 / 16", "-2 / 3", "8 / 7", "5", "-3", "-3", //over largest int value
    "2147,483,647 / 2,147,483,648", //over largest long value
    "9,223,372,036,854,775,807 / 9,223,372,036,854,775,808" };
    final BigFraction[] fractions = { BigFraction.of(1, 2), BigFraction.of(-1, 2), BigFraction.of(1, -2), BigFraction.of(-1, -2), BigFraction.of(1, 2), BigFraction.of(1, 2), BigFraction.of(-1, 2), BigFraction.of(1, -2), BigFraction.of(15, 16), BigFraction.of(-2, 3), BigFraction.of(8, 7), BigFraction.of(5, 1), BigFraction.of(-3, 1), BigFraction.of(3, -1), BigFraction.of(2147483647, 2147483648L), BigFraction.of(new BigInteger("9223372036854775807"), new BigInteger("9223372036854775808")) };
    int inc = 0;
    for (final BigFraction fraction : fractions) {
        Assertions.assertEquals(fraction, BigFraction.parse(validExpressions[inc]));
        inc++;
    }
    Assertions.assertThrows(NumberFormatException.class, () -> BigFraction.parse("1 // 2"));
