        final double actual = Gamma.value(x);
        final double absX = Math.abs(x);
        final int ulps;
        if (absX <= 8.0) {
            ulps = 3;
        } else if (absX <= 20.0) {
            ulps = 5;
        } else if (absX <= 30.0) {
            ulps = 50;
        } else if (absX <= 50.0) {
            ulps = 180;
        } else {
            ulps = 500;
