@Test
void testTrigamma() {
    double eps = 1e-8;
    // computed using webMathematica.  For example, to compute trigamma($i) = Polygamma(1, $i), use
    //
    // http://functions.wolfram.com/webMathematica/Evaluated.jsp?name=PolyGamma2&plottype=0&vars={%221%22,%22$i%22}&digits=20
    double[] data = { 0.0, Double.POSITIVE_INFINITY, 1e-11, 1e22, 1e-10, 1e20, 1e-9, 1.0000000000000000016e18, 1e-8, 1.0000000000000001645e16, 1e-7, 1.0000000000000164493e14, 1e-6, 1.0000000000016449317e12, 1e-5, 1.0000000001644910026e10, 1e-4, 1.0000000164469368793e8, 1e-3, 1.0000016425331958690e6, 1e-2, 10001.621213528313220, 1e-1, 101.43329915079275882, 1, 1.6449340668482264365, 2, 0.64493406684822643647, 3, 0.39493406684822643647, 4, 0.28382295573711532536, 5, 0.22132295573711532536, 10, 0.10516633568168574612, 20, 0.051270822935203119832, 50, 0.020201333226697125806, 100, 0.010050166663333571395 };
    for (int i = data.length - 2; i >= 0; i -= 2) {
        final double value = data[i];
        final double expected = data[i + 1];
        // Allowed error is 1e-8 relative or absolute error whichever is larger.
        final double error = Math.max(expected * eps, eps);
        Assertions.assertEquals(expected, Trigamma.value(value), error, () -> "trigamma " + value);
    }
}

