    Assertions.assertFalse(q1.equals(q4, 0.9 * inc));
    Assertions.assertFalse(q1.equals(q5, 0.9 * inc));
    Assertions.assertTrue(q1.equals(q2, 1.1 * inc));
    Assertions.assertTrue(q1.equals(q3, 1.1 * inc));
