    Assertions.assertArrayEquals(new double[] { 0, 2, 1 }, transformVector(slerp.apply(0.5), vec), EPS);
    Assertions.assertArrayEquals(new double[] { -SQRT_2, SQRT_2, 1 }, transformVector(slerp.apply(0.75), vec), EPS);
