@Test
void testVectorTransform_multipleCombinations() {
    // arrange
    Quaternion[] quaternions = { // +x axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, INV_SQRT_2, 0, 0), // pi
    Quaternion.of(0, 1, 0, 0), // -x axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, -INV_SQRT_2, 0, 0), // pi
    Quaternion.of(0, -1, 0, 0), // +y axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, INV_SQRT_2, 0), // pi
    Quaternion.of(0, 0, 1, 0), // -y axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, -INV_SQRT_2, 0), // pi
    Quaternion.of(0, 0, -1, 0), // +z axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, 0, INV_SQRT_2), // pi
    Quaternion.of(0, 0, 0, 1), // -z axis
    // 0 pi
    Quaternion.of(1, 0, 0, 0), // pi/2
    Quaternion.of(INV_SQRT_2, 0, 0, -INV_SQRT_2), // pi
    Quaternion.of(0, 0, 0, -1) };
    // act/assert
    // test each quaternion against all of the others (including itself)
    for (int i = 0; i < quaternions.length; ++i) {
        for (int j = 0; j < quaternions.length; ++j) {
            checkSlerpCombination(quaternions[i], quaternions[j]);
        }
    }
}

